// src/pages/UserLogin.jsx
import React, { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import axios from "axios";
import { useNavigate, Link } from "react-router-dom";
import { useAuthStore } from "../store/authStore";

// ✅ Default to backend URL if env is missing
const API_URL =
  import.meta.env.VITE_API_BASE_URL ||
  "https://ecommerce-project-production-28e7.up.railway.app";

export default function UserLogin() {
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm();
  const setToken = useAuthStore((state) => state.setToken);
  const navigate = useNavigate();

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // ✅ Auto-login if token exists in localStorage
  useEffect(() => {
    const savedToken = localStorage.getItem("authToken");
    if (savedToken) {
      setToken(savedToken);
      navigate("/");
    }
  }, [setToken, navigate]);

  const onSubmit = async (data) => {
    setError("");
    setLoading(true);
    try {
      const res = await axios.post(`${API_URL}/auth/login`, data);
      const token = res.data.token;

      if (!token) throw new Error("No token returned from server");

      // ✅ Save token in Zustand and localStorage
      setToken(token);
      localStorage.setItem("authToken", token);

      navigate("/"); // Redirect to homepage
    } catch (err) {
      console.error("❌ Login failed:", err);
      setError(
        err.response?.data?.message ||
          err.message ||
          "Invalid email or password. Try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-sm mx-auto p-6 mt-10 border rounded shadow bg-white">
      <h2 className="text-2xl font-bold mb-4 text-center">User Login</h2>

      {error && (
        <div className="mb-4 text-red-600 text-sm bg-red-100 p-2 rounded">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
        <div>
          <input
            {...register("email", { required: "Email is required" })}
            type="email"
            className="w-full border p-2 rounded"
            placeholder="Email"
          />
          {errors.email && (
            <p className="text-red-500 text-sm mt-1">
              {errors.email.message}
            </p>
          )}
        </div>

        <div>
          <input
            {...register("password", { required: "Password is required" })}
            type="password"
            className="w-full border p-2 rounded"
            placeholder="Password"
          />
          {errors.password && (
            <p className="text-red-500 text-sm mt-1">
              {errors.password.message}
            </p>
          )}
        </div>

        <button
          type="submit"
          disabled={loading}
          className={`w-full text-white p-2 rounded ${
            loading
              ? "bg-blue-400 cursor-not-allowed"
              : "bg-blue-600 hover:bg-blue-700"
          }`}
        >
          {loading ? "Logging in..." : "Login"}
        </button>
      </form>

      <div className="mt-4 text-sm flex justify-between">
        <Link to="/forgot-password" className="text-blue-600 hover:underline">
          Forgot Password?
        </Link>
        <Link to="/signup" className="text-blue-600 hover:underline">
          Create Account
        </Link>
      </div>
    </div>
  );
}
